// Arma el payload del recordatorio desde la lectura fresca del doc.
const norm = $('Normalizar entrada1').first()?.json || {};
const docNorm = $('Normalizar datos Firestore1').first()?.json || {};
const document_id = String($input.first()?.json?._id || $input.first()?.json?.id || docNorm.document_id || norm.document_id || '').trim();
const rawInput = ($input.first() || {}).json || {};

// El nodo Firestore nativo de n8n puede devolver datos de dos formas:
// 1. Planos: { customerPhone: "549...", customerName: "...", ... }
// 2. Con wrapper REST API: { fields: { customerPhone: { stringValue: "549..." } } }
const getField = (d, k) => {
  if (!d || typeof d !== 'object') return null;
  // Formato REST API (via HTTP): d.fields[k].stringValue
  if (d.fields && d.fields[k] !== undefined) {
    const f = d.fields[k];
    if (f === null || f === undefined) return null;
    if (f.stringValue !== undefined) return f.stringValue;
    if (f.integerValue !== undefined) return parseInt(f.integerValue);
    if (f.booleanValue !== undefined) return f.booleanValue;
    if (f.doubleValue !== undefined) return parseFloat(f.doubleValue);
    return null;
  }
  // Formato plano (nodo nativo n8n): d[k]
  const v = d[k];
  if (v === undefined || v === null) return null;
  // A veces el nodo nativo anida el valor como objeto con stringValue
  if (typeof v === 'object' && v.stringValue !== undefined) return v.stringValue;
  if (typeof v === 'object' && v.integerValue !== undefined) return parseInt(v.integerValue);
  return v;
};

const normalizePhone = (v) => {
  let s = String(v || '').replace(/@s\.whatsapp\.net$/i, '').replace(/[^0-9]/g, '');
  if (!s) return '';
  if (s.startsWith('0')) s = s.slice(1);
  if (s.startsWith('54')) return s;
  const m = s.match(/^(\d{2,4})15(\d{6,8})$/);
  if (m) s = m[1] + '9' + m[2];
  return '54' + s;
};

if (!document_id) return [];
const estado = String(getField(rawInput, 'estado') || '').toLowerCase();
if (!rawInput || rawInput.error) return [];
if (['cancelado', 'cancelada', 'no_show', 'ausente', 'finalizado'].includes(estado)) return [];
if (getField(rawInput, 'recordatorio15_enviado') === true) return [];

const time = getField(rawInput, 'time');
const name = String(getField(rawInput, 'customerName') || '').trim();
const phone = normalizePhone(getField(rawInput, 'customerPhone') || getField(rawInput, 'phone'));
const mesaRaw = String(getField(rawInput, 'mesa') || getField(rawInput, 'tableId') || getField(rawInput, 'mesa_id') || '');
if (!time || !name || !phone) return [];
const dateStr = getField(rawInput, 'date');
if (dateStr && time) {
  const nowMs = Date.now();
  const resTimeMs = new Date(dateStr + 'T' + time + ':00-03:00').getTime();
  // Si falta MUCHO para la reserva (más de 25 minutos) o ya pasó la hora, abortar.
  if (resTimeMs - nowMs > 25 * 60000 || resTimeMs < nowMs) return [];
}
const mesaNum = mesaRaw.replace(/^mesa\s+/i, '').replace(/^m(?=\d)/i, '');

return [{ json: {
  document_id,
  reminder_key: 'reminder15_' + document_id,
  phone,
  name,
  time,
  mesa: mesaNum,
} }];
